"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["5206"],{27811(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.processo_seletivo.fato_coletado_sem_valores_ofertados","status":422,"titulo":"O fato coletado \xe9 de sele\xe7\xe3o, mas o processo n\xe3o declara nenhuma op\xe7\xe3o para ele"},"descricao":{"codigo":"uniplus.selecao.processo_seletivo.fato_coletado_sem_valores_ofertados","requisitos":[],"oQueAconteceu":["Um campo de escolha (\xfanica ou m\xfaltipla) do formul\xe1rio publicaria sem nenhuma op\xe7\xe3o a\\noferecer, obrigat\xf3rio ou opcional: a pessoa candidata teria um seletor vazio. O rascunho\\naceita o v\xednculo incompleto; quem barra \xe9 a opera\xe7\xe3o que gera vers\xe3o. A mensagem de\\ndetalhe cita o c\xf3digo do fato e diz qual \xe9 a falta, que pode ser:","- o campo tem as op\xe7\xf5es do pr\xf3prio processo, e o processo n\xe3o declara nenhuma para ele\\n  (\xe9 o caso da condi\xe7\xe3o de atendimento, do recurso de acessibilidade e de fatos cujas\\n  op\xe7\xf5es o processo declara);\\n- o campo oferece os munic\xedpios do b\xf4nus regional, e o processo n\xe3o tem b\xf4nus regional;\\n- o campo oferece os tipos do cadastro de tipos de defici\xeancia, e o cadastro n\xe3o tem\\n  nenhum tipo ativo;\\n- o conjunto de op\xe7\xf5es do campo ficou vazio quando a vers\xe3o foi montada.","A recusa sai com **422**, antes de gerar a vers\xe3o."],"comoResolver":["Corrija a falta que a mensagem aponta e repita a opera\xe7\xe3o:","- para op\xe7\xf5es do processo, declare ao menos uma\\n  (`PUT /api/selecao/processos-seletivos/{id}/fatos/{fatoCodigo}/opcoes`); para a\\n  condi\xe7\xe3o de atendimento e o recurso de acessibilidade, as op\xe7\xf5es v\xeam do atendimento\\n  especializado\\n  (`PUT /api/selecao/processos-seletivos/{id}/atendimento-especializado`);\\n- para os munic\xedpios do b\xf4nus regional, declare o b\xf4nus regional\\n  (`PUT /api/selecao/processos-seletivos/{id}/bonus-regional`) ou retire o campo do\\n  formul\xe1rio;\\n- para os tipos de defici\xeancia, a gest\xe3o do cadastro deve ativar ao menos um tipo.","Se o campo n\xe3o \xe9 necess\xe1rio, retire-o do formul\xe1rio."],"ondeAparece":["Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Processo seletivo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);